const EMBEDDED = {"files":{"/index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, user-scalable=no, interactive-widget=resizes-content\">\n<title>Buddymon Gold</title>\n<link rel=\"icon\" href=\"data:,\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Lilita+One&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"style.css\">\n<link rel=\"stylesheet\" href=\"hd.bundle.css\">\n</head>\n<body>\n<main>\n  <div id=\"screen-wrap\">\n    <canvas id=\"screen\" width=\"160\" height=\"144\"></canvas>\n    <div id=\"hd\"></div>\n    <div id=\"start\">\n      <select id=\"game\" aria-label=\"Game\">\n        <option value=\"gold\">Buddymon Gold</option>\n      </select>\n      <button id=\"play\">Play</button>\n    </div>\n  </div>\n\n  <div id=\"pad\" hidden>\n    <div id=\"dpad\" aria-label=\"Directional pad\"><i class=\"u\"></i><i class=\"d\"></i><i class=\"l\"></i><i class=\"r\"></i></div>\n    <div class=\"center\">\n      <button data-key=\"SELECT\">Select</button>\n      <button data-key=\"START\">Start</button>\n    </div>\n    <div class=\"ab\">\n      <button data-key=\"B\">B</button>\n      <button data-key=\"A\">A</button>\n    </div>\n  </div>\n\n  <section id=\"cloud\">\n    <span id=\"status\">Not playing</span>\n    <button id=\"sync\" disabled>Save to cloud</button>\n    <button id=\"code\">Recovery code…</button>\n  </section>\n  <p class=\"hint\">Keys: arrows, Z = B, X = A, Enter = Start, Shift = Select.\n    Use the in-game SAVE menu; it syncs to the cloud automatically.</p>\n</main>\n<script src=\"https://cdn.jsdelivr.net/npm/wasmboy@0.7.1/dist/wasmboy.wasm.iife.js\"></script>\n<script src=\"hd.bundle.js\"></script>\n<script src=\"app.js\"></script>\n</body>\n</html>\n","/app.js":"\"use strict\";\n\nconst WB = WasmBoy.WasmBoy;\n\nconst SAVE_SIZE = 0x8000;\nconst SYNC_INTERVAL_MS = 30000;\n\nconst $ = (id) => document.getElementById(id);\nconst canvas = $(\"screen\");\nconst statusEl = $(\"status\");\nconst syncBtn = $(\"sync\");\n\nlet game = null;\nlet lastSynced = null; // hash of the last RAM we sent to / got from the cloud\nlet syncing = false;\n\nconst setStatus = (text) => (statusEl.textContent = text);\n\nasync function api(path, options = {}) {\n  return fetch(path, { credentials: \"same-origin\", ...options });\n}\n\nfunction hash(bytes) {\n  let h = 2166136261;\n  for (let i = 0; i < bytes.length; i++) h = Math.imul(h ^ bytes[i], 16777619);\n  return h >>> 0;\n}\n\nasync function ensurePlayer() {\n  const res = await api(\"/api/me\");\n  if (!res.ok) throw new Error(\"Could not reach the save server\");\n  return (await res.json()).code;\n}\n\n// The emulator only refreshes its copy of cartridge RAM when paused.\nasync function readRam() {\n  const wasPlaying = WB.isPlaying();\n  if (wasPlaying) await WB.pause();\n  try {\n    const info = await WB._getCartridgeInfo();\n    return info.RAM ? new Uint8Array(info.RAM) : null;\n  } finally {\n    if (wasPlaying) await WB.play();\n  }\n}\n\n// Inject a battery save by loading it into a fresh-boot save state.\nasync function writeRam(ram) {\n  await WB.pause();\n  const state = await WB.saveState();\n  state.wasmboyMemory.cartridgeRam = ram;\n  await WB.loadState(state);\n}\n\nasync function pushToCloud({ force = false } = {}) {\n  if (!game || syncing) return;\n  syncing = true;\n  try {\n    const ram = await readRam();\n    if (!ram || ram.length !== SAVE_SIZE) return;\n    const h = hash(ram);\n    if (!force && h === lastSynced) return;\n    const res = await api(`/api/save/${game}`, { method: \"PUT\", body: ram });\n    if (!res.ok) throw new Error(`server said ${res.status}`);\n    lastSynced = h;\n    setStatus(`Saved to cloud at ${new Date().toLocaleTimeString()}`);\n  } catch (err) {\n    setStatus(`Cloud save failed: ${err.message}`);\n  } finally {\n    syncing = false;\n  }\n}\n\nasync function start() {\n  game = $(\"game\").value;\n  $(\"play\").disabled = true;\n  setStatus(\"Loading…\");\n  try {\n    await ensurePlayer();\n    const rom = await (await fetch(`roms/poke${game}.gbc`)).arrayBuffer();\n\n    await WB.config(\n      {\n        isGbcEnabled: true,\n        isAudioEnabled: true,\n        headless: false,\n        isGbcColorizationEnabled: false,\n        enableBootROMIfAvailable: false,\n        gameboyFrameRate: 60,\n        maxNumberOfAutoSaveStates: 0,\n      },\n      canvas\n    );\n    await WB.loadROM(new Uint8Array(rom));\n\n    const res = await api(`/api/save/${game}`);\n    if (res.ok) {\n      const cloud = new Uint8Array(await res.arrayBuffer());\n      const local = await readRam();\n      lastSynced = hash(cloud);\n      const differs = !local || hash(local) !== lastSynced;\n      const localEmpty = !local || local.every((b) => b === 0 || b === 0xff);\n      if (differs && (localEmpty || confirm(\"A cloud save exists and differs from this device's save.\\nOK = use the cloud save, Cancel = keep this device's save.\"))) {\n        await writeRam(cloud);\n      }\n    }\n\n    await WB.play();\n    HD.start(WB, $(\"hd\"), Scenes);\n    $(\"start\").hidden = true;\n    $(\"pad\").hidden = false;\n    syncBtn.disabled = false;\n    setStatus(\"Playing\");\n    setInterval(pushToCloud, SYNC_INTERVAL_MS);\n    document.addEventListener(\"visibilitychange\", () => document.hidden && pushToCloud());\n  } catch (err) {\n    console.error(err);\n    setStatus(`Error: ${err.message}`);\n    $(\"play\").disabled = false;\n  }\n}\n\n$(\"play\").addEventListener(\"click\", start);\nsyncBtn.addEventListener(\"click\", () => pushToCloud({ force: true }));\n\n$(\"code\").addEventListener(\"click\", async () => {\n  const code = await ensurePlayer();\n  const entered = prompt(\n    \"Your recovery code (keep it private). Paste a code from another device here to switch to that player's saves:\",\n    code\n  );\n  if (entered && entered.trim() !== code) {\n    const res = await api(\"/api/me\", { method: \"POST\", body: JSON.stringify({ code: entered.trim() }) });\n    setStatus(res.ok ? \"Switched player; reload to load their save\" : \"Invalid code\");\n  }\n});\n\n// On-screen pad. WasmBoy re-applies its own input state every frame, so pad presses are\n// merged into that state with a plugin (calling setJoypadState directly gets overwritten\n// next frame). A press is held at least MIN_HOLD_MS so a tap can't fall between frames.\nconst MIN_HOLD_MS = 110;\nconst PAD_KEYS = [\"UP\", \"DOWN\", \"LEFT\", \"RIGHT\", \"A\", \"B\", \"START\", \"SELECT\"];\nconst held = {}, pressedAt = {}, releaseTimer = {};\n\nWB.ResponsiveGamepad.addPlugin({\n  name: \"touch-pad\",\n  onGetState(state) {\n    for (const k of PAD_KEYS) state[k] = state[k] || !!held[k];\n    return state;\n  },\n});\n\nfunction setKey(key, down) {\n  if (down) {\n    clearTimeout(releaseTimer[key]);\n    if (held[key]) return;\n    held[key] = true;\n    pressedAt[key] = performance.now();\n  } else if (held[key]) {\n    const wait = Math.max(0, MIN_HOLD_MS - (performance.now() - pressedAt[key]));\n    releaseTimer[key] = setTimeout(() => { held[key] = false; }, wait);\n  }\n}\n\nfor (const btn of document.querySelectorAll(\"#pad [data-key]\")) {\n  const key = btn.dataset.key;\n  const up = () => { btn.classList.remove(\"down\"); setKey(key, false); };\n  btn.addEventListener(\"pointerdown\", (e) => { e.preventDefault(); btn.setPointerCapture(e.pointerId); btn.classList.add(\"down\"); setKey(key, true); });\n  btn.addEventListener(\"pointerup\", up);\n  btn.addEventListener(\"pointercancel\", up);\n}\n\n// One touch surface for the D-pad so a thumb can roll between directions.\nconst dpad = $(\"dpad\");\nlet dpadDir = null;\nfunction setDpad(dir) {\n  if (dir === dpadDir) return;\n  if (dpadDir) setKey(dpadDir, false);\n  dpad.className = dir || \"\";\n  dpadDir = dir;\n  if (dir) setKey(dir, true);\n}\nfunction dpadFromEvent(e) {\n  const r = dpad.getBoundingClientRect();\n  const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);\n  if (Math.hypot(dx, dy) < r.width * 0.12) return null;\n  return Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? \"LEFT\" : \"RIGHT\") : (dy < 0 ? \"UP\" : \"DOWN\");\n}\ndpad.addEventListener(\"pointerdown\", (e) => { e.preventDefault(); dpad.setPointerCapture(e.pointerId); setDpad(dpadFromEvent(e)); });\ndpad.addEventListener(\"pointermove\", (e) => { if (dpad.hasPointerCapture(e.pointerId)) setDpad(dpadFromEvent(e)); });\ndpad.addEventListener(\"pointerup\", () => setDpad(null));\ndpad.addEventListener(\"pointercancel\", () => setDpad(null));\ndocument.addEventListener(\"contextmenu\", (e) => e.preventDefault());\n","/hd.bundle.css":"/* ui/dialogue.css */\n/* dialogue */\n#hd .dlg { position:absolute; left:3.5%; right:3.5%; bottom:3.5%; height:27%; padding:3.8cqw 5cqw 2cqw; border-radius:4cqw;\n  background:linear-gradient(rgba(18,32,82,.94),rgba(10,18,50,.96)); border:.7cqw solid var(--gold); box-shadow:0 0 0 .5cqw var(--ink), 0 1.6cqw 4cqw rgba(0,0,0,.5); }\n#hd .dlg[hidden] { display:none; }\n#hd .dlg p { margin:0; font-size:5.6cqw; line-height:1.28; font-weight:500; min-height:7.2cqw; text-shadow:0 .3cqw 0 rgba(0,0,0,.35); }\n#hd .dlg-tag { position:absolute; left:4cqw; top:-3.6cqw; padding:.5cqw 3cqw; font-size:3.4cqw; font-weight:700; color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); border:.5cqw solid var(--ink); border-radius:3cqw; }\n#hd .more { position:absolute; right:4cqw; bottom:2cqw; font-size:4cqw; color:var(--gold); animation:nudge .9s ease-in-out infinite; }\n@keyframes nudge { 50% { transform:translateY(.8cqw); } }\n\n\n/* ui/portrait.css */\n/* portrait (shared by prof, names, naming) */\n#hd .portrait { position:absolute; left:4%; bottom:30%; width:54%; filter:drop-shadow(0 1.6cqw 0 rgba(0,0,0,.25)); }\n#hd .portrait svg { width:100%; display:block; }\n\n/* scenes/clock.css */\n/* clock */\n#hd .card { position:absolute; left:50%; top:20%; transform:translateX(-50%); width:46%; padding:3cqw; text-align:center; border-radius:5cqw;\n  background:linear-gradient(rgba(18,32,82,.96),rgba(10,18,50,.96)); border:.7cqw solid var(--gold); box-shadow:0 0 0 .5cqw var(--ink), 0 0 4cqw rgba(255,201,60,.35); }\n#hd .card[hidden], #hd .choice[hidden] { display:none; }\n#hd .card .cap { display:block; font-size:3.6cqw; opacity:.8; } #hd .card .big { display:block; font-size:20cqw; line-height:1; color:var(--gold); font-family:'Lilita One','Fredoka',sans-serif; text-shadow:0 .8cqw 0 var(--ink); }\n#hd .card .sub { font-size:4cqw; }\n#hd .choice { position:absolute; right:5%; bottom:33%; display:flex; flex-direction:column; gap:2cqw; }\n#hd .choice button { font:inherit; font-weight:700; font-size:5cqw; padding:1.6cqw 8cqw; border-radius:4cqw; border:.5cqw solid rgba(255,246,220,.3); color:var(--cream); background:rgba(10,18,50,.85); }\n#hd .choice button.sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); border-color:var(--ink); box-shadow:0 .8cqw 0 var(--gold2); }\n\n\n/* scenes/menu.css */\n/* menu */\n#hd .menu-list { position:absolute; left:6%; top:46%; margin:0; padding:0; list-style:none; width:64%; }\n#hd .menu-list li { position:relative; margin:0 0 3cqw; padding:2.4cqw 4cqw 2.4cqw 7cqw; font-size:5.2cqw; font-weight:600; border-radius:4cqw;\n  background:rgba(10,18,50,.72); border:.5cqw solid rgba(255,246,220,.25); backdrop-filter:blur(4px); transition:transform .12s; }\n#hd .menu-list li b { position:absolute; left:3cqw; top:50%; width:2.2cqw; height:2.2cqw; margin-top:-1.1cqw; border-radius:50%; background:transparent; }\n#hd .menu-list li.sel { transform:translateX(2cqw) scale(1.04); color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); border-color:var(--ink); box-shadow:0 1cqw 0 var(--gold2), 0 0 3cqw rgba(255,201,60,.55); }\n#hd .menu-list li.sel b { background:var(--ink); }\n#hd .chip { position:absolute; right:4%; top:4%; padding:1.4cqw 3cqw; font-size:3.4cqw; border-radius:4cqw; background:rgba(10,18,50,.7); border:.4cqw solid rgba(255,246,220,.25); white-space:pre; }\n\n\n/* scenes/names.css */\n/* name choice */\n#hd .names .portrait { bottom:5%; width:56%; left:22%; }\n#hd .panel { position:absolute; left:8%; right:8%; top:6%; padding:3cqw; border-radius:5cqw; background:rgba(10,18,50,.85); border:.6cqw solid var(--gold); }\n#hd .panel h2 { margin:0 0 2.5cqw; font-size:4.6cqw; text-align:center; font-weight:700; }\n#hd .panel ul { margin:0; padding:0; list-style:none; }\n#hd .panel li { margin:0 0 1.6cqw; padding:1.6cqw 3cqw; font-size:4.6cqw; border-radius:3cqw; background:rgba(255,246,220,.08); }\n#hd .panel li.sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); font-weight:700; }\n\n/* scenes/naming.css */\n/* naming keyboard */\n#hd .naming .portrait { left:5%; top:3%; bottom:auto; width:20%; }\n#hd .entry { position:absolute; left:30%; right:5%; top:5%; padding:2.4cqw 3cqw; border-radius:4cqw; background:rgba(10,18,50,.85); border:.6cqw solid var(--gold); }\n#hd .entry h2 { margin:0 0 1.6cqw; font-size:4cqw; font-weight:700; text-align:center; }\n#hd .slots { display:flex; gap:1.4cqw; justify-content:center; }\n#hd .slots span { width:7.4cqw; height:9cqw; line-height:9cqw; text-align:center; font-size:6cqw; font-weight:700; border-radius:2cqw; background:rgba(255,246,220,.1); border-bottom:.7cqw solid rgba(255,246,220,.4); }\n#hd .slots span.on { border-bottom-color:var(--gold); box-shadow:0 0 2cqw rgba(255,201,60,.6); }\n#hd .kb { position:absolute; left:5%; right:5%; bottom:4%; display:grid; grid-template-columns:repeat(9,1fr); gap:1.4cqw; padding:2.6cqw; border-radius:4cqw; background:rgba(10,18,50,.85); border:.6cqw solid rgba(255,246,220,.3); }\n#hd .kb b, #hd .kb em { display:flex; align-items:center; justify-content:center; height:8.6cqw; font-style:normal; font-size:4.6cqw; font-weight:600; border-radius:2.2cqw; background:rgba(255,246,220,.1); }\n#hd .kb b.gap { background:none; }\n#hd .kb em.wide { grid-column:span 3; font-size:4cqw; }\n#hd .kb .sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); box-shadow:0 .7cqw 0 var(--gold2); transform:scale(1.08); }\n\n/* scenes/prof.css */\n/* professor intro */\n#hd .creature { position:absolute; right:5%; top:6%; width:38%; padding:2cqw; border-radius:6cqw; background:rgba(255,246,220,.14); border:.5cqw solid rgba(255,246,220,.35); animation:hop 2.8s ease-in-out infinite; }\n#hd .creature[hidden] { display:none; } #hd .creature svg { width:100%; display:block; }\n\n/* scenes/room.css */\n/* room */\n#hd .room { background:radial-gradient(90% 80% at 50% 45%, #25407a 0%, #0c1636 100%); }\n#hd .room-wrap { position:absolute; left:50%; top:44%; width:98%; transform:translate(-50%,-50%); filter:drop-shadow(0 2cqw 3cqw rgba(0,0,0,.5)); }\n#hd .room-svg { width:100%; display:block; }\n#hd .hero { position:absolute; width:14%; aspect-ratio:60/80; transform:translate(-50%,-100%); transition:left .14s linear, top .14s linear; }\n#hd .hero svg { width:100%; height:100%; display:block; overflow:visible; }\n#hd .hero.walk svg { animation:step .22s ease-in-out; }\n@keyframes step { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-6%)} }\n#hd .loc { position:absolute; left:4%; top:3%; padding:1cqw 3cqw; font-size:3cqw; border-radius:3cqw; background:rgba(10,18,50,.7); border:.4cqw solid rgba(255,246,220,.25); }\n\n\n/* scenes/title.css */\n/* title */\n#hd .logo { position:absolute; left:5%; right:5%; top:4%; filter:drop-shadow(0 1.4cqw 0 rgba(0,0,0,.25)); animation:bob 4.5s ease-in-out infinite; }\n#hd .logo .logo-svg { width:100%; display:block; }\n#hd .logo.small { left:3%; right:auto; width:52%; top:3%; animation:none; }\n@keyframes bob { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-1.2cqw)} }\n#hd .trio { position:absolute; left:0; right:0; bottom:9%; height:36%; }\n#hd .mon { position:absolute; bottom:0; animation:hop 2.8s ease-in-out infinite; }\n#hd .mon svg { width:100%; height:100%; display:block; }\n#hd .m1 { left:10%; width:25%; animation-delay:.2s } #hd .m2 { left:37%; width:27%; bottom:2%; animation-delay:.9s } #hd .m3 { left:66%; width:25%; animation-delay:1.5s }\n@keyframes hop { 0%,100%{transform:translateY(0)} 45%{transform:translateY(-3cqw)} 60%{transform:translateY(0) scale(1.02,.97)} }\n#hd .press { position:absolute; left:0; right:0; bottom:3.2%; text-align:center; font-weight:700; font-size:4.6cqw; letter-spacing:.5cqw;\n  color:var(--cream); text-shadow:0 0 1.6cqw rgba(255,201,60,.8), 0 .5cqw 0 var(--ink); animation:blink 1.4s ease-in-out infinite; }\n@keyframes blink { 0%,100%{opacity:1} 50%{opacity:.25} }\n#hd .fly { position:absolute; width:.9cqw; height:.9cqw; border-radius:50%; background:#ffe98a; box-shadow:0 0 1.6cqw .6cqw rgba(255,233,138,.7); animation:float 6s ease-in-out infinite; }\n@keyframes float { 0%,100%{transform:translate(0,0);opacity:.2} 50%{transform:translate(3cqw,-5cqw);opacity:1} }\n\n\n/* core/base.css */\n/* Buddymon HD layer. Sized in cqw so it scales with the game screen. */\n:root { --ink:#0b1730; --gold:#ffc93c; --gold2:#f08a14; --cream:#fff6dc; --navy:#10204f; --teal:#3de0c4; --coral:#ff6b5e; }\n\n#hd { position:absolute; inset:0; container-type:size; overflow:hidden; border-radius:6px; display:none;\n  font-family:'Fredoka',system-ui,sans-serif; color:var(--cream); background:#050a22; user-select:none; pointer-events:none; }\n.hd-on #hd { display:block; }\n.hd-on #screen { visibility:hidden; }\n#hd .scene { position:absolute; inset:0; overflow:hidden; }\n#hd .sky, #hd .sky-svg { position:absolute; inset:0; width:100%; height:100%; }\n#hd .sky.dim { filter:brightness(.55) saturate(.9); }\n#hd .sky.warm { background:radial-gradient(120% 90% at 50% 100%, #ffb76b 0%, #f08a5a 38%, #7a4a9c 78%, #2b2a6b 100%); }\n#hd .star { animation:twinkle 3.6s ease-in-out infinite; }\n@keyframes twinkle { 0%,100%{opacity:.25} 50%{opacity:1} }\n#hd .clouds { animation:drift 40s linear infinite alternate; }\n@keyframes drift { to { transform:translateX(120px); } }\n\n\n@media (prefers-reduced-motion: reduce) { #hd *, #hd *::before { animation:none !important; transition:none !important; } }\n","/hd.bundle.js":"\"use strict\";\n/* core/registry.js */\n// Registries the art/ and scenes/ files add to. Loaded first by bundle.js.\nconst INK = \"#0b1730\";\nconst Art = {};\nconst Scenes = {};\n\n/* ui/dialogue.js */\n// Bottom text box fed by state.dialogue (see core/engine.js).\nfunction dialogue(parent, tag) {\n  const el = h(`<div class=\"dlg\" hidden>${tag ? `<div class=\"dlg-tag\">${tag}</div>` : \"\"}<p class=\"l1\"></p><p class=\"l2\"></p><span class=\"more\">▼</span></div>`);\n  parent.appendChild(el);\n  return {\n    el,\n    setTag(t) { const tg = el.querySelector(\".dlg-tag\"); if (tg) tg.textContent = t; },\n    update(d) {\n      el.hidden = !d;\n      if (!d) return;\n      el.querySelector(\".l1\").textContent = d.lines[0];\n      el.querySelector(\".l2\").textContent = d.lines[1];\n      el.querySelector(\".more\").style.visibility = d.more ? \"visible\" : \"hidden\";\n    },\n  };\n}\n\n\n/* ui/dom.js */\n// DOM helpers shared by scenes.\nfunction h(html) { const t = document.createElement(\"template\"); t.innerHTML = html.trim(); return t.content.firstChild; }\n\n// Night-sky backdrop used behind several scenes.\nfunction sky() { return h(`<div class=\"sky\">${Art.sky()}<i class=\"glow\"></i></div>`); }\n\n/* ui/list.js */\n// Every row of a bordered list menu: [{ label, selected }]\nfunction listItems(state, firstCol, lastCol, firstRow = 1, lastRow = 11) {\n  const items = [];\n  for (let r = firstRow; r <= lastRow; r++) {\n    const label = HD.text(state, r, firstCol, lastCol).replace(/[▶▷]/g, \"\").trim();\n    const cursor = state.tiles[r * 20 + firstCol - 1] === 0xed;\n    if (label && !/^[┌─┐│└┘]+$/.test(label)) items.push({ label, selected: cursor });\n  }\n  return items;\n}\n\n/* art/_eye.js */\n// Shared eye: white sclera, coloured iris, ink pupil, two glints.\nArt.eye = function (cx, cy, r, iris = \"#e04a4a\") {\n  return `<g><ellipse cx=\"${cx}\" cy=\"${cy}\" rx=\"${r}\" ry=\"${r * 1.12}\" fill=\"#fff\" stroke=\"${INK}\" stroke-width=\"3.5\"/>\n    <ellipse cx=\"${cx + r * 0.08}\" cy=\"${cy + r * 0.1}\" rx=\"${r * 0.68}\" ry=\"${r * 0.78}\" fill=\"${iris}\"/>\n    <ellipse cx=\"${cx + r * 0.1}\" cy=\"${cy + r * 0.12}\" rx=\"${r * 0.36}\" ry=\"${r * 0.42}\" fill=\"${INK}\"/>\n    <circle cx=\"${cx - r * 0.22}\" cy=\"${cy - r * 0.3}\" r=\"${r * 0.22}\" fill=\"#fff\"/>\n    <circle cx=\"${cx + r * 0.3}\" cy=\"${cy + r * 0.28}\" r=\"${r * 0.1}\" fill=\"#fff\"/></g>`;\n};\n\n/* art/bramblet.js */\n// BRAMBLET: leaf-spined hedgehog (grass starter)\nArt.bramblet = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"bb-leaf\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#58d684\"/><stop offset=\"1\" stop-color=\"#1f8f4e\"/></linearGradient>\n<linearGradient id=\"bb-fur\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffd9a0\"/><stop offset=\"1\" stop-color=\"#eeb06b\"/></linearGradient>\n</defs>\n<ellipse cx=\"100\" cy=\"184\" rx=\"58\" ry=\"9\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#bb-leaf)\" d=\"M22 130 C10 100 20 66 46 50 L50 78 L58 30 L82 62 L100 14 L118 62 L142 30 L150 78 L154 50 C180 66 190 100 178 130 C160 150 40 150 22 130 Z\"/>\n<path fill=\"#7be8a0\" stroke-width=\"3\" d=\"M58 30 L66 70 L74 56 Z M100 14 L96 62 L108 62 Z M142 30 L126 56 L134 70 Z\"/>\n<ellipse cx=\"68\" cy=\"172\" rx=\"20\" ry=\"12\" fill=\"url(#bb-fur)\"/>\n<ellipse cx=\"132\" cy=\"172\" rx=\"20\" ry=\"12\" fill=\"url(#bb-fur)\"/>\n<ellipse cx=\"100\" cy=\"138\" rx=\"46\" ry=\"38\" fill=\"url(#bb-fur)\"/>\n<ellipse cx=\"100\" cy=\"148\" rx=\"26\" ry=\"22\" fill=\"#fff4d6\" stroke=\"none\"/>\n<circle cx=\"58\" cy=\"76\" r=\"14\" fill=\"url(#bb-fur)\"/><circle cx=\"58\" cy=\"76\" r=\"7\" fill=\"#ff9aa8\" stroke=\"none\"/>\n<circle cx=\"142\" cy=\"76\" r=\"14\" fill=\"url(#bb-fur)\"/><circle cx=\"142\" cy=\"76\" r=\"7\" fill=\"#ff9aa8\" stroke=\"none\"/>\n<ellipse cx=\"100\" cy=\"100\" rx=\"50\" ry=\"42\" fill=\"url(#bb-fur)\"/>\n</g>\n<path d=\"M74 66 Q100 52 126 66\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\".55\"/>\n${this.eye(78, 98, 12, \"#2e9e55\")}${this.eye(122, 98, 12, \"#2e9e55\")}\n<ellipse cx=\"100\" cy=\"114\" rx=\"8\" ry=\"6\" fill=\"${INK}\"/>\n<path d=\"M92 124 Q100 132 108 124\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n<circle cx=\"64\" cy=\"116\" r=\"8\" fill=\"#ff8c9e\" opacity=\".7\"/><circle cx=\"136\" cy=\"116\" r=\"8\" fill=\"#ff8c9e\" opacity=\".7\"/>\n</svg>`;\n};\n\n/* art/chomplet.js */\n// CHOMPLET: shark pup (water starter), after the supplied reference style\nArt.chomplet = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"ch-body\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#4fb6d9\"/><stop offset=\"1\" stop-color=\"#2a6fa8\"/></linearGradient>\n<linearGradient id=\"ch-mouth\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#d63a4a\"/><stop offset=\"1\" stop-color=\"#8f1f36\"/></linearGradient>\n</defs>\n<ellipse cx=\"100\" cy=\"188\" rx=\"58\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#ch-body)\" d=\"M104 10 C132 24 140 46 140 66 L66 66 C84 52 100 34 104 10 Z\"/>\n<path fill=\"url(#ch-body)\" d=\"M26 150 C22 100 52 66 100 66 C148 66 178 100 174 150 C170 176 140 188 100 188 C60 188 30 176 26 150 Z\"/>\n<path fill=\"#ffe08a\" stroke=\"none\" d=\"M44 160 C60 178 140 178 156 160 C150 186 50 186 44 160 Z\"/>\n<path fill=\"url(#ch-body)\" d=\"M30 140 L8 156 L30 166 Z\"/><path fill=\"url(#ch-body)\" d=\"M170 140 L192 156 L170 166 Z\"/>\n<path fill=\"url(#ch-mouth)\" d=\"M44 112 C66 130 134 130 156 112 C160 146 134 172 100 172 C66 172 40 146 44 112 Z\"/>\n</g>\n<g fill=\"#fff\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\">\n<path d=\"M50 114 L62 132 L72 118 Z\"/><path d=\"M76 120 L88 138 L98 124 Z\"/><path d=\"M102 124 L112 138 L124 120 Z\"/><path d=\"M128 118 L138 132 L150 114 Z\"/>\n</g>\n<path d=\"M82 160 C90 148 110 148 118 160 C112 170 88 170 82 160 Z\" fill=\"#ff8da1\" stroke=\"${INK}\" stroke-width=\"4\"/>\n<path d=\"M66 92 L90 86\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M134 92 L110 86\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n${this.eye(72, 100, 12, \"#e04a4a\")}${this.eye(128, 100, 12, \"#e04a4a\")}\n<path d=\"M84 52 C92 40 98 30 100 22\" fill=\"none\" stroke=\"#bfeaff\" stroke-width=\"5\" stroke-linecap=\"round\" opacity=\".7\"/>\n</svg>`;\n};\n\n/* art/hero.js */\n// Player portrait: the kid in the cap (viewBox 300 x 380)\nArt.hero = function () {\n  return `<svg viewBox=\"0 0 300 380\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"hr-jacket\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffb62e\"/><stop offset=\"1\" stop-color=\"#e57d12\"/></linearGradient>\n<linearGradient id=\"hr-cap\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ff6b5e\"/><stop offset=\"1\" stop-color=\"#c9322a\"/></linearGradient>\n</defs>\n<g stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#hr-jacket)\" d=\"M24 380 C24 304 66 266 112 256 L188 256 C234 266 276 304 276 380 Z\"/>\n<path fill=\"#1f3a8a\" d=\"M112 256 L150 336 L188 256 L168 250 L150 292 L132 250 Z\"/>\n<rect x=\"126\" y=\"218\" width=\"48\" height=\"44\" rx=\"14\" fill=\"#e9b184\"/>\n<ellipse cx=\"150\" cy=\"168\" rx=\"66\" ry=\"70\" fill=\"#f4c397\"/>\n<path fill=\"#3a2418\" d=\"M82 150 C84 110 116 96 150 96 C184 96 216 110 218 150 C200 134 176 128 150 128 C124 128 100 134 82 150 Z\"/>\n<path fill=\"url(#hr-cap)\" d=\"M78 134 C80 66 120 40 154 40 C192 40 224 70 222 134 C196 118 104 118 78 134 Z\"/>\n<path fill=\"url(#hr-cap)\" d=\"M96 128 C130 112 214 112 248 138 C226 150 124 146 96 128 Z\"/>\n<circle cx=\"150\" cy=\"82\" r=\"16\" fill=\"#ffd25a\"/>\n</g>\n<circle cx=\"120\" cy=\"172\" r=\"9\" fill=\"${INK}\"/><circle cx=\"180\" cy=\"172\" r=\"9\" fill=\"${INK}\"/>\n<circle cx=\"117\" cy=\"169\" r=\"3.4\" fill=\"#fff\"/><circle cx=\"177\" cy=\"169\" r=\"3.4\" fill=\"#fff\"/>\n<path d=\"M132 200 Q150 216 168 200\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n<circle cx=\"102\" cy=\"196\" r=\"9\" fill=\"#ff8c9e\" opacity=\".6\"/><circle cx=\"198\" cy=\"196\" r=\"9\" fill=\"#ff8c9e\" opacity=\".6\"/>\n</svg>`;\n};\n\n/* art/heroSprite.js */\n// Tiny overworld hero. dir: 0 down, 1 up, 2 left, 3 right (viewBox 60 x 80)\nArt.heroSprite = function (dir) {\n  const face = dir === 1 ? \"\" : dir === 0\n    ? `<circle cx=\"24\" cy=\"30\" r=\"3\" fill=\"${INK}\"/><circle cx=\"36\" cy=\"30\" r=\"3\" fill=\"${INK}\"/>`\n    : `<circle cx=\"${dir === 2 ? 21 : 39}\" cy=\"30\" r=\"3\" fill=\"${INK}\"/>`;\n  const visor = dir === 1 ? \"\" : dir === 0\n    ? `<path d=\"M14 22 Q30 32 46 22 Q30 16 14 22\" fill=\"#c9322a\"/>`\n    : `<path d=\"${dir === 2 ? \"M8 24 Q20 20 30 22 L30 28 Q18 28 8 24\" : \"M52 24 Q40 20 30 22 L30 28 Q42 28 52 24\"}\" fill=\"#c9322a\"/>`;\n  return `<svg viewBox=\"0 0 60 80\" xmlns=\"http://www.w3.org/2000/svg\">\n<ellipse cx=\"30\" cy=\"74\" rx=\"18\" ry=\"5\" fill=\"#000\" opacity=\".25\"/>\n<g stroke=\"${INK}\" stroke-width=\"3.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path class=\"leg l\" fill=\"#1f3a8a\" d=\"M20 56 L28 56 L28 70 L18 70 Z\"/><path class=\"leg r\" fill=\"#1f3a8a\" d=\"M32 56 L40 56 L42 70 L32 70 Z\"/>\n<path fill=\"#ffb62e\" d=\"M16 56 C14 44 20 40 30 40 C40 40 46 44 44 56 Z\"/>\n<circle cx=\"30\" cy=\"28\" r=\"15\" fill=\"#f4c397\"/>\n<path fill=\"${dir === 1 ? \"#3a2418\" : \"#c9322a\"}\" d=\"M14 26 C14 8 46 8 46 26 C38 20 22 20 14 26 Z\"/>\n${dir === 1 ? `<path fill=\"#c9322a\" d=\"M15 26 C15 10 45 10 45 26 C38 22 22 22 15 26 Z\"/>` : \"\"}\n</g>\n${face}${dir === 1 ? \"\" : visor}\n</svg>`;\n};\n\n/* art/logo.js */\nArt.logo = function () {\n  return `<svg class=\"logo-svg\" viewBox=\"0 0 1000 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"gold\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fff3a8\"/><stop offset=\".5\" stop-color=\"#ffc93c\"/><stop offset=\"1\" stop-color=\"#f08a14\"/></linearGradient>\n<linearGradient id=\"rib\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#2b4ea8\"/><stop offset=\"1\" stop-color=\"#16295f\"/></linearGradient>\n<clipPath id=\"top-half\"><rect x=\"0\" y=\"0\" width=\"1000\" height=\"112\"/></clipPath>\n</defs>\n<g font-family=\"'Lilita One','Fredoka',system-ui,sans-serif\" text-anchor=\"middle\" stroke-linejoin=\"round\">\n<text x=\"500\" y=\"192\" font-size=\"172\" fill=\"#b84a12\" stroke=\"${INK}\" stroke-width=\"34\" paint-order=\"stroke\">BUDDYMON</text>\n<text x=\"500\" y=\"176\" font-size=\"172\" fill=\"url(#gold)\" stroke=\"${INK}\" stroke-width=\"30\" paint-order=\"stroke\">BUDDYMON</text>\n<text x=\"500\" y=\"176\" font-size=\"172\" fill=\"#fff\" opacity=\".45\" clip-path=\"url(#top-half)\">BUDDYMON</text>\n</g>\n<path d=\"M300 226 L700 226 L730 260 L700 294 L300 294 L270 260 Z\" fill=\"url(#rib)\" stroke=\"${INK}\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n<path d=\"M300 236 L700 236\" stroke=\"#6f93ff\" stroke-width=\"3\" opacity=\".6\"/>\n<text x=\"500\" y=\"282\" text-anchor=\"middle\" font-family=\"'Lilita One','Fredoka',system-ui,sans-serif\" font-size=\"58\" letter-spacing=\"14\" fill=\"url(#gold)\" stroke=\"${INK}\" stroke-width=\"8\" paint-order=\"stroke\">GOLD</text>\n<path d=\"M270 260 l-26 -20 l0 40 z M730 260 l26 -20 l0 40 z\" fill=\"#ffc93c\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\"/>\n</svg>`;\n};\n\n/* art/professor.js */\n// Friendly professor, bust portrait (viewBox 300 x 380)\nArt.professor = function () {\n  return `<svg viewBox=\"0 0 300 380\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"pf-coat\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffffff\"/><stop offset=\"1\" stop-color=\"#d8e2f2\"/></linearGradient>\n<linearGradient id=\"pf-hair\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#e6ebf5\"/><stop offset=\"1\" stop-color=\"#b9c2d8\"/></linearGradient>\n</defs>\n<g stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#pf-coat)\" d=\"M20 380 C20 300 60 262 110 252 L190 252 C240 262 280 300 280 380 Z\"/>\n<path fill=\"#2fae6b\" d=\"M112 252 L150 300 L188 252 L168 246 L150 270 L132 246 Z\"/>\n<path fill=\"#fff\" d=\"M104 250 L150 322 L124 372 L82 292 Z\"/><path fill=\"#fff\" d=\"M196 250 L150 322 L176 372 L218 292 Z\"/>\n<rect x=\"124\" y=\"214\" width=\"52\" height=\"44\" rx=\"14\" fill=\"#f2c29a\"/>\n<path fill=\"url(#pf-hair)\" d=\"M60 170 C52 70 120 30 150 30 C190 30 250 66 240 170 C246 214 230 240 212 246 L212 150 L88 150 L88 246 C70 238 56 214 60 170 Z\"/>\n<ellipse cx=\"150\" cy=\"168\" rx=\"70\" ry=\"76\" fill=\"#f7d0a8\"/>\n<path fill=\"url(#pf-hair)\" d=\"M78 150 C86 82 126 66 150 66 C180 66 218 84 224 150 C206 120 180 104 150 104 C120 104 96 118 78 150 Z\"/>\n</g>\n<g fill=\"none\" stroke=\"${INK}\" stroke-width=\"5\" stroke-linecap=\"round\">\n<circle cx=\"118\" cy=\"168\" r=\"24\" fill=\"#cfe9ff\" fill-opacity=\".35\"/><circle cx=\"182\" cy=\"168\" r=\"24\" fill=\"#cfe9ff\" fill-opacity=\".35\"/>\n<path d=\"M142 166 Q150 160 158 166\"/>\n<path d=\"M96 164 L84 160 M204 164 L216 160\"/>\n<path d=\"M126 218 Q150 236 174 218\"/>\n</g>\n<circle cx=\"118\" cy=\"170\" r=\"8\" fill=\"${INK}\"/><circle cx=\"182\" cy=\"170\" r=\"8\" fill=\"${INK}\"/>\n<circle cx=\"115\" cy=\"167\" r=\"3\" fill=\"#fff\"/><circle cx=\"179\" cy=\"167\" r=\"3\" fill=\"#fff\"/>\n<circle cx=\"102\" cy=\"196\" r=\"10\" fill=\"#ff9aa8\" opacity=\".55\"/><circle cx=\"198\" cy=\"196\" r=\"10\" fill=\"#ff9aa8\" opacity=\".55\"/>\n<path d=\"M124 150 q14 -10 28 -2 M148 148 q14 -8 28 2\" fill=\"none\" stroke=\"#8793ad\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n<g transform=\"translate(206 282)\"><path d=\"M0 0 c0 -16 14 -22 26 -22 c0 14 -8 24 -26 22z\" fill=\"#46c26f\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linejoin=\"round\"/></g>\n</svg>`;\n};\n\n/* art/room.js */\n// The player's bedroom: an 8 x 6 grid, one cell = 100 units. Layout mirrors the\n// game's collision: PC and radio on the desk (2,1)-(3,1), TV (4,1) with console\n// (4,2), bookshelf (5,1), stairs (7,0), table (4,4)-(5,4), bed (0,4)-(0,5).\nArt.room = function () {\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n  let planks = \"\";\n  for (let i = 1; i < 12; i++) planks += `<path d=\"M0 ${100 + i * 42} H800\" stroke=\"#c98d4a\" stroke-width=\"2\" opacity=\".45\"/>`;\n  return `<svg class=\"room-svg\" viewBox=\"-20 -20 840 640\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"fl\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f0be78\"/><stop offset=\"1\" stop-color=\"#d99a54\"/></linearGradient>\n<linearGradient id=\"wl\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3b57b0\"/><stop offset=\"1\" stop-color=\"#27408a\"/></linearGradient>\n<linearGradient id=\"bed\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#ff8a6b\"/><stop offset=\"1\" stop-color=\"#e5604a\"/></linearGradient>\n<radialGradient id=\"lamp\"><stop offset=\"0\" stop-color=\"#ffe9a8\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#ffe9a8\" stop-opacity=\"0\"/></radialGradient>\n</defs>\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"600\" rx=\"10\" fill=\"url(#fl)\"/>${planks}\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"110\" fill=\"url(#wl)\"/>\n<g stroke=\"#4a68c8\" stroke-width=\"2\" opacity=\".5\">${Array.from({ length: 16 }, (_, i) => `<path d=\"M${25 + i * 50} 0 V100\"/>`).join(\"\")}</g>\n<rect x=\"0\" y=\"96\" width=\"800\" height=\"16\" fill=\"#f4e3c1\" ${o}/>\n<rect x=\"-6\" y=\"-6\" width=\"812\" height=\"612\" rx=\"12\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"12\"/>\n<!-- window -->\n<g ${o}><rect x=\"40\" y=\"14\" width=\"110\" height=\"74\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M95 14 V88 M40 51 H150\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<circle cx=\"72\" cy=\"36\" r=\"9\" fill=\"#ffd35a\" stroke=\"none\"/><circle cx=\"120\" cy=\"66\" r=\"2.5\" fill=\"#fff\" stroke=\"none\"/><circle cx=\"62\" cy=\"68\" r=\"2\" fill=\"#fff\" stroke=\"none\"/></g>\n<!-- poster -->\n<g ${o} transform=\"translate(600 10)\"><rect width=\"90\" height=\"76\" rx=\"5\" fill=\"#fff4d6\"/><path d=\"M10 62 L32 30 L48 50 L60 38 L82 62 Z\" fill=\"#46c26f\"/><circle cx=\"66\" cy=\"22\" r=\"9\" fill=\"#ffc93c\"/></g>\n<!-- stairs -->\n<g ${o}><rect x=\"710\" y=\"6\" width=\"84\" height=\"94\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M718 30 H786 M718 52 H786 M718 74 H786\" stroke=\"#6f86d6\" stroke-width=\"5\"/><path d=\"M752 82 l-12 -14 h24 z\" fill=\"#ffc93c\" stroke=\"${INK}\" stroke-width=\"3\"/></g>\n<!-- rug -->\n<ellipse cx=\"400\" cy=\"320\" rx=\"230\" ry=\"96\" fill=\"#2fae6b\" ${o} opacity=\".92\"/><ellipse cx=\"400\" cy=\"320\" rx=\"196\" ry=\"74\" fill=\"none\" stroke=\"#7be8a0\" stroke-width=\"5\" stroke-dasharray=\"14 10\"/>\n<!-- shadows -->\n<g fill=\"#000\" opacity=\".16\"><ellipse cx=\"270\" cy=\"212\" rx=\"120\" ry=\"14\"/><ellipse cx=\"610\" cy=\"212\" rx=\"58\" ry=\"14\"/></g>\n<!-- desk with PC + radio (x 2-3, y 1) -->\n<g ${o}>\n<rect x=\"198\" y=\"118\" width=\"206\" height=\"92\" rx=\"8\" fill=\"#b8763a\"/><rect x=\"208\" y=\"128\" width=\"186\" height=\"14\" fill=\"#d79a5a\" stroke=\"none\"/>\n<rect x=\"214\" y=\"68\" width=\"82\" height=\"62\" rx=\"8\" fill=\"#e9eef8\"/><rect x=\"224\" y=\"76\" width=\"62\" height=\"42\" rx=\"4\" fill=\"#1b2d6b\"/><path d=\"M232 90 H268 M232 100 H256\" stroke=\"#7be8a0\" stroke-width=\"4\"/>\n<rect x=\"222\" y=\"148\" width=\"70\" height=\"20\" rx=\"4\" fill=\"#e9eef8\"/>\n<rect x=\"318\" y=\"108\" width=\"72\" height=\"50\" rx=\"8\" fill=\"#ff6b5e\"/><circle cx=\"342\" cy=\"134\" r=\"14\" fill=\"#ffe0dc\"/><path d=\"M366 120 H382 M366 134 H382 M366 148 H382\" stroke=\"${INK}\" stroke-width=\"3\"/>\n<path d=\"M206 210 V224 M396 210 V224\" stroke-width=\"8\"/>\n</g>\n<!-- TV + console (x 4, y 1-2) -->\n<g ${o}>\n<rect x=\"416\" y=\"62\" width=\"86\" height=\"130\" rx=\"10\" fill=\"#3a56b0\"/><rect x=\"426\" y=\"72\" width=\"66\" height=\"52\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M432 84 L486 112\" stroke=\"#6f86d6\" stroke-width=\"4\" opacity=\".6\"/>\n<rect x=\"428\" y=\"140\" width=\"62\" height=\"40\" rx=\"6\" fill=\"#e9eef8\"/><circle cx=\"446\" cy=\"160\" r=\"7\" fill=\"#ff6b5e\"/><rect x=\"460\" y=\"152\" width=\"22\" height=\"16\" rx=\"3\" fill=\"#7be8a0\"/>\n<rect x=\"424\" y=\"214\" width=\"70\" height=\"40\" rx=\"8\" fill=\"#6f86d6\"/><circle cx=\"446\" cy=\"234\" r=\"8\" fill=\"#ffd35a\"/><path d=\"M470 226 v16 M462 234 h16\" stroke=\"${INK}\" stroke-width=\"4\"/>\n</g>\n<!-- bookshelf (x 5, y 1) -->\n<g ${o}>\n<rect x=\"516\" y=\"52\" width=\"86\" height=\"148\" rx=\"8\" fill=\"#b8763a\"/>\n<rect x=\"526\" y=\"64\" width=\"66\" height=\"38\" fill=\"#7a4a1e\" stroke=\"none\"/><rect x=\"526\" y=\"112\" width=\"66\" height=\"38\" fill=\"#7a4a1e\" stroke=\"none\"/>\n<g stroke-width=\"3\"><rect x=\"530\" y=\"68\" width=\"12\" height=\"32\" fill=\"#e04a4a\"/><rect x=\"544\" y=\"72\" width=\"12\" height=\"28\" fill=\"#46c26f\"/><rect x=\"558\" y=\"66\" width=\"12\" height=\"34\" fill=\"#ffc93c\"/><rect x=\"572\" y=\"72\" width=\"14\" height=\"28\" fill=\"#4fb6d9\"/>\n<rect x=\"530\" y=\"118\" width=\"16\" height=\"30\" fill=\"#ffc93c\"/><rect x=\"548\" y=\"114\" width=\"12\" height=\"34\" fill=\"#e04a4a\"/><rect x=\"562\" y=\"120\" width=\"22\" height=\"28\" fill=\"#6f86d6\"/></g>\n<rect x=\"526\" y=\"160\" width=\"66\" height=\"30\" fill=\"#7a4a1e\" stroke=\"none\"/><circle cx=\"560\" cy=\"174\" r=\"11\" fill=\"#7be8a0\" stroke-width=\"3\"/>\n</g>\n<!-- table (x 4-5, y 4) -->\n<g ${o}>\n<rect x=\"408\" y=\"410\" width=\"204\" height=\"74\" rx=\"10\" fill=\"#c98446\"/><rect x=\"418\" y=\"418\" width=\"184\" height=\"12\" fill=\"#e2a468\" stroke=\"none\"/>\n<path d=\"M424 484 V510 M596 484 V510\" stroke-width=\"9\"/>\n<rect x=\"440\" y=\"436\" width=\"46\" height=\"30\" rx=\"6\" fill=\"#ffe0dc\" stroke-width=\"4\"/>\n<circle cx=\"548\" cy=\"448\" r=\"20\" fill=\"#fff4d6\" stroke-width=\"4\"/><path d=\"M548 428 v-14\" stroke-width=\"4\"/>\n</g>\n<!-- bed (x 0, y 4-5) -->\n<g ${o}>\n<rect x=\"6\" y=\"404\" width=\"98\" height=\"190\" rx=\"12\" fill=\"url(#bed)\"/>\n<rect x=\"14\" y=\"412\" width=\"82\" height=\"52\" rx=\"12\" fill=\"#fff4d6\"/>\n<path d=\"M6 480 Q55 462 104 480\" fill=\"none\" stroke=\"#ffd0c4\" stroke-width=\"5\"/>\n</g>\n<ellipse cx=\"260\" cy=\"150\" rx=\"190\" ry=\"110\" fill=\"url(#lamp)\"/>\n</svg>`;\n};\n\n/* art/sky.js */\n// Night sky with a big golden moon and layered hills. `dim` darkens it for menus.\nArt.sky = function () {\n  let stars = \"\";\n  let seed = 7;\n  const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);\n  for (let i = 0; i < 70; i++) {\n    const x = rnd() * 1000, y = rnd() * 520, r = 1 + rnd() * 2.4;\n    stars += `<circle class=\"star\" style=\"animation-delay:${(rnd() * 4).toFixed(2)}s\" cx=\"${x.toFixed(0)}\" cy=\"${y.toFixed(0)}\" r=\"${r.toFixed(1)}\" fill=\"#fff6dc\"/>`;\n  }\n  return `<svg class=\"sky-svg\" viewBox=\"0 0 1000 900\" preserveAspectRatio=\"xMidYMid slice\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"sk\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#050a22\"/><stop offset=\".55\" stop-color=\"#1b2d6b\"/><stop offset=\".85\" stop-color=\"#5a4a8c\"/><stop offset=\"1\" stop-color=\"#e98a58\"/></linearGradient>\n<radialGradient id=\"moon-glow\"><stop offset=\"0\" stop-color=\"#ffd35a\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#ffd35a\" stop-opacity=\"0\"/></radialGradient>\n<linearGradient id=\"moon\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fff1b0\"/><stop offset=\"1\" stop-color=\"#ffb62e\"/></linearGradient>\n<linearGradient id=\"h1\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3a3f86\"/><stop offset=\"1\" stop-color=\"#252a64\"/></linearGradient>\n<linearGradient id=\"h2\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#27346f\"/><stop offset=\"1\" stop-color=\"#17214f\"/></linearGradient>\n<linearGradient id=\"h3\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#1b7a5a\"/><stop offset=\"1\" stop-color=\"#0d4237\"/></linearGradient>\n</defs>\n<rect width=\"1000\" height=\"900\" fill=\"url(#sk)\"/>\n${stars}\n<circle cx=\"500\" cy=\"330\" r=\"330\" fill=\"url(#moon-glow)\"/>\n<circle cx=\"500\" cy=\"330\" r=\"150\" fill=\"url(#moon)\" stroke=\"${INK}\" stroke-width=\"6\"/>\n<circle cx=\"455\" cy=\"290\" r=\"26\" fill=\"#ffc94a\" opacity=\".55\"/><circle cx=\"548\" cy=\"372\" r=\"18\" fill=\"#ffc94a\" opacity=\".5\"/><circle cx=\"520\" cy=\"270\" r=\"11\" fill=\"#ffc94a\" opacity=\".5\"/>\n<g class=\"clouds\"><path d=\"M80 210 q30 -40 70 -10 q40 -30 70 10 z\" fill=\"#fff\" opacity=\".12\"/><path d=\"M700 160 q30 -40 70 -10 q40 -30 70 10 z\" fill=\"#fff\" opacity=\".12\"/></g>\n<path d=\"M0 640 C150 560 270 600 400 560 C560 510 720 590 1000 540 L1000 900 L0 900 Z\" fill=\"url(#h1)\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<path d=\"M0 720 C180 650 330 700 520 650 C700 610 850 690 1000 660 L1000 900 L0 900 Z\" fill=\"url(#h2)\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<path d=\"M0 800 C200 750 360 800 560 760 C760 725 880 790 1000 770 L1000 900 L0 900 Z\" fill=\"url(#h3)\" stroke=\"${INK}\" stroke-width=\"5\"/>\n</svg>`;\n};\n\n/* art/sparkit.js */\n// SPARKIT: ember fox (fire starter)\nArt.sparkit = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"sp-body\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffa24a\"/><stop offset=\"1\" stop-color=\"#e5602a\"/></linearGradient>\n<linearGradient id=\"sp-flame\" x1=\"0\" y1=\"1\" x2=\"0\" y2=\"0\"><stop offset=\"0\" stop-color=\"#ff7a1a\"/><stop offset=\"1\" stop-color=\"#ffe066\"/></linearGradient>\n</defs>\n<ellipse cx=\"100\" cy=\"186\" rx=\"56\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#sp-body)\" d=\"M138 168 C196 168 196 112 170 96 C176 124 160 140 140 142 Z\"/>\n<path fill=\"url(#sp-flame)\" d=\"M170 96 C160 80 170 62 184 50 C186 68 198 78 190 98 C186 106 176 108 170 96 Z\"/>\n<ellipse cx=\"72\" cy=\"176\" rx=\"18\" ry=\"11\" fill=\"#fff0d4\"/>\n<ellipse cx=\"128\" cy=\"176\" rx=\"18\" ry=\"11\" fill=\"#fff0d4\"/>\n<ellipse cx=\"100\" cy=\"142\" rx=\"40\" ry=\"36\" fill=\"url(#sp-body)\"/>\n<ellipse cx=\"100\" cy=\"152\" rx=\"22\" ry=\"20\" fill=\"#fff0d4\" stroke=\"none\"/>\n<path fill=\"url(#sp-body)\" d=\"M44 74 L46 14 L84 52 Z\"/><path fill=\"#5a1d2a\" stroke=\"none\" d=\"M54 62 L54 32 L72 52 Z\"/>\n<path fill=\"url(#sp-body)\" d=\"M156 74 L154 14 L116 52 Z\"/><path fill=\"#5a1d2a\" stroke=\"none\" d=\"M146 62 L146 32 L128 52 Z\"/>\n<path fill=\"url(#sp-body)\" d=\"M40 96 C36 66 66 48 100 48 C134 48 164 66 160 96 C158 120 130 136 100 136 C70 136 42 120 40 96 Z\"/>\n<path fill=\"#fff0d4\" stroke=\"none\" d=\"M70 112 C80 100 120 100 130 112 C126 128 74 128 70 112 Z\"/>\n<path fill=\"url(#sp-flame)\" d=\"M100 28 C92 40 94 52 100 58 C106 52 108 40 100 28 Z\" stroke-width=\"4\"/>\n</g>\n${this.eye(76, 94, 11, \"#7a3b00\")}${this.eye(124, 94, 11, \"#7a3b00\")}\n<path d=\"M92 108 L108 108 L100 118 Z\" fill=\"${INK}\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\"/>\n<path d=\"M100 118 L100 124 M88 126 Q100 134 112 126\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n<circle cx=\"58\" cy=\"112\" r=\"8\" fill=\"#ff7a8a\" opacity=\".6\"/><circle cx=\"142\" cy=\"112\" r=\"8\" fill=\"#ff7a8a\" opacity=\".6\"/>\n</svg>`;\n};\n\n/* scenes/clock.js */\nScenes.clock = function (root) {\n  const el = h(`<div class=\"scene clock\">\n    <div class=\"card time\" hidden><span class=\"cap\">Time</span><b class=\"big\"></b><span class=\"sub\"></span></div>\n    <div class=\"choice\" hidden><button data-v=\"YES\">Yes</button><button data-v=\"NO\">No</button></div>\n  </div>`);\n  el.prepend(sky());\n  el.querySelector(\".sky\").classList.add(\"dim\");\n  root.appendChild(el);\n  const dlg = dialogue(el);\n  const card = el.querySelector(\".time\"), choice = el.querySelector(\".choice\");\n  return {\n    update(state) {\n      dlg.update(state.dialogue);\n      let hours = null, minutes = null, day = null;\n      for (const row of state.rows) {\n        let m;\n        if ((m = row.match(/(\\d+)\\s*o'clock/))) hours = m[1];\n        if ((m = row.match(/(\\d+)\\s*min/))) minutes = m[1];\n        if ((m = row.match(/(SUN|MON|TUES|WEDNES|THURS|FRI|SATUR)DAY/))) day = m[0];\n      }\n      const showCard = hours !== null || minutes !== null;\n      card.hidden = !showCard;\n      if (showCard) {\n        card.querySelector(\".big\").textContent = minutes !== null ? minutes : hours;\n        card.querySelector(\".sub\").textContent = minutes !== null ? \"minutes\" : \"o'clock\";\n        card.querySelector(\".cap\").textContent = day ? day[0] + day.slice(1).toLowerCase() : \"Time\";\n      }\n      const yes = state.rows.findIndex((r) => /(^|\\s)YES\\b/.test(r.replace(/[▶▷]/g, \"\")));\n      choice.hidden = yes < 0;\n      if (yes >= 0) {\n        const cursorOnYes = state.tiles[yes * 20 + 15] === 0xed || /▶\\s*YES/.test(state.rows[yes]);\n        choice.children[0].classList.toggle(\"sel\", cursorOnYes);\n        choice.children[1].classList.toggle(\"sel\", !cursorOnYes);\n      }\n    },\n  };\n};\n\n/* scenes/menu.js */\nconst MENU_LABELS = { \"CONTINUE\": \"Continue\", \"NEW GAME\": \"New Game\", \"OPTION\": \"Options\", \"MYSTERY GIFT\": \"Mystery Gift\" };\n\nScenes.menu = function (root) {\n  const el = h(`<div class=\"scene menu\">\n    <div class=\"logo small\">${Art.logo()}</div>\n    <ul class=\"menu-list\"></ul>\n    <div class=\"chip\" hidden></div>\n  </div>`);\n  el.prepend(sky());\n  root.appendChild(el);\n  const list = el.querySelector(\"ul\"), chip = el.querySelector(\".chip\");\n  let last = \"\";\n  return {\n    update(state) {\n      const items = listItems(state, 2, 14, 1, 10);\n      const info = [13, 14, 15, 16, 17].map((r) => HD.text(state, r, 1, 19).replace(/[┌─┐│└┘]/g, \"\").trim()).filter(Boolean);\n      const key = JSON.stringify([items, info]);\n      if (key === last) return;\n      last = key;\n      list.innerHTML = items.map((i) => `<li class=\"${i.selected ? \"sel\" : \"\"}\"><b></b>${MENU_LABELS[i.label] || i.label}</li>`).join(\"\");\n      chip.hidden = !info.length;\n      chip.textContent = info.join(\"  \");\n    },\n  };\n};\n\n/* scenes/names.js */\nScenes.names = function (root) {\n  const el = h(`<div class=\"scene names\">\n    <div class=\"portrait\">${Art.hero()}</div>\n    <div class=\"panel\"><h2>What's your name?</h2><ul></ul></div>\n  </div>`);\n  el.prepend(h(`<div class=\"sky warm\"></div>`));\n  root.appendChild(el);\n  const ul = el.querySelector(\"ul\");\n  let last = \"\";\n  return {\n    update(state) {\n      const items = listItems(state, 2, 10, 1, 11);\n      const key = JSON.stringify(items);\n      if (key === last) return;\n      last = key;\n      ul.innerHTML = items.map((i) => `<li class=\"${i.selected ? \"sel\" : \"\"}\">${i.label === \"NEW NAME\" ? \"New name…\" : i.label}</li>`).join(\"\");\n    },\n  };\n};\n\n/* scenes/naming.js */\nScenes.naming = function (root) {\n  const el = h(`<div class=\"scene naming\">\n    <div class=\"portrait\">${Art.hero()}</div>\n    <div class=\"entry\"><h2>Your name?</h2><div class=\"slots\"></div></div>\n    <div class=\"kb\"></div>\n  </div>`);\n  el.prepend(h(`<div class=\"sky warm\"></div>`));\n  root.appendChild(el);\n  const slots = el.querySelector(\".slots\"), kb = el.querySelector(\".kb\");\n  let last = \"\";\n  return {\n    update(state) {\n      const firstCol = Math.min(...HD.cells(state, 8).map((c) => c.col));\n      const grid = [8, 10, 12, 14].map((r) => {\n        const row = Array(9).fill(\"\");\n        for (const { col, ch } of HD.cells(state, r)) {\n          const i = Math.round((col - firstCol) / 2);\n          if (i >= 0 && i < 9) row[i] = ch;\n        }\n        return row;\n      });\n      const bottom = HD.text(state, 16, 1, 19);\n      const typed = HD.text(state, 6, 3, 19).replace(/\\s+/g, \"\");\n      const cur = state.naming || { col: -1, row: -1, max: 7 };\n      const key = JSON.stringify([grid, bottom, typed, cur]);\n      if (key === last) return;\n      last = key;\n      slots.innerHTML = Array.from({ length: cur.max || 7 }, (_, i) =>\n        `<span class=\"${i === typed.length ? \"on\" : \"\"}\">${typed[i] || \"\"}</span>`).join(\"\");\n      const bottomSel = cur.row === 4 ? (cur.col < 3 ? 0 : cur.col < 6 ? 1 : 2) : -1;\n      const lower = /^\\s*upper/i.test(bottom) ? \"ABC\" : \"abc\";\n      kb.innerHTML = grid.map((row, r) => row.map((ch, c) =>\n        ch ? `<b class=\"${cur.row === r && cur.col === c ? \"sel\" : \"\"}\">${ch}</b>` : `<b class=\"gap\"></b>`).join(\"\")).join(\"\") +\n        [lower === \"abc\" ? \"abc\" : \"ABC\", \"Delete\", \"Done\"].map((t, i) => `<em class=\"wide ${bottomSel === i ? \"sel\" : \"\"}\">${t}</em>`).join(\"\");\n    },\n  };\n};\n\n/* scenes/prof.js */\n// Species shown on the pixel screen -> HD art.\nconst SPECIES_ART = { 152: \"bramblet\", 155: \"sparkit\", 158: \"chomplet\" };\n\nScenes.prof = function (root, flags) {\n  const el = h(`<div class=\"scene prof\">\n    <div class=\"lab\"></div>\n    <div class=\"portrait\"></div>\n    <div class=\"creature\" hidden></div>\n  </div>`);\n  el.prepend(h(`<div class=\"sky warm\"></div>`));\n  root.appendChild(el);\n  const dlg = dialogue(el, \"PROF. WILLOW\");\n  const portrait = el.querySelector(\".portrait\"), creature = el.querySelector(\".creature\");\n  let who = null, shown = null;\n  return {\n    update(state) {\n      const nextWho = flags.seenNaming ? \"hero\" : \"professor\";\n      if (nextWho !== who) {\n        who = nextWho;\n        portrait.innerHTML = Art[who]();\n        dlg.setTag(who === \"hero\" ? (state.name || \"YOU\") : \"PROF. WILLOW\");\n      }\n      dlg.update(state.dialogue);\n      const art = SPECIES_ART[state.species] || null;\n      if (art !== shown) {\n        shown = art;\n        creature.hidden = !art;\n        creature.innerHTML = art ? Art[art]() : \"\";\n      }\n    },\n  };\n};\n\n/* scenes/room.js */\nScenes.room = function (root) {\n  const el = h(`<div class=\"scene room\">\n    <div class=\"vignette\"></div>\n    <div class=\"room-wrap\">${Art.room()}<div class=\"hero\"></div></div>\n    <div class=\"loc\">Home · Your Room</div>\n  </div>`);\n  root.appendChild(el);\n  const hero = el.querySelector(\".hero\");\n  const dlg = dialogue(el);\n  let dir = -1, px = null, py = null, walkUntil = 0;\n  const place = (x, y) => {\n    hero.style.left = `${((x * 100 + 50 + 20) / 840) * 100}%`;\n    hero.style.top = `${((y * 100 + 92 + 20) / 640) * 100}%`;\n  };\n  return {\n    update(state) {\n      if (state.dir !== dir) { dir = state.dir; hero.innerHTML = Art.heroSprite(dir); }\n      if (state.x !== px || state.y !== py) {\n        if (px !== null) walkUntil = performance.now() + 220;\n        px = state.x; py = state.y;\n        place(px, py);\n      }\n      hero.classList.toggle(\"walk\", performance.now() < walkUntil);\n      dlg.update(state.dialogue);\n    },\n  };\n};\n\n/* scenes/title.js */\nScenes.title = function (root) {\n  const el = h(`<div class=\"scene title\">\n    <div class=\"logo\">${Art.logo()}</div>\n    <div class=\"trio\">\n      <div class=\"mon m1\">${Art.bramblet()}</div><div class=\"mon m2\">${Art.sparkit()}</div><div class=\"mon m3\">${Art.chomplet()}</div>\n    </div>\n    <div class=\"press\">PRESS START</div>\n  </div>`);\n  el.prepend(sky());\n  for (let i = 0; i < 14; i++) {\n    const f = h(`<i class=\"fly\" style=\"left:${(i * 73) % 100}%;top:${48 + ((i * 37) % 40)}%;animation-delay:${(i * 0.7) % 5}s\"></i>`);\n    el.appendChild(f);\n  }\n  root.appendChild(el);\n  return { update() {} };\n};\n\n/* core/engine.js */\n\"use strict\";\n// HD layer core: reads the emulator's memory, works out which screen the game\n// is showing, and lets a scene in scenes.js draw it as crisp DOM/SVG.\n// Whatever isn't redrawn falls back to the normal pixel canvas.\n\nconst HD = (() => {\n  // WasmBoy keeps work RAM (0xC000-0xDFFF, banks 0 and 1) contiguous here.\n  const WRAM_START = 0x4800;\n  const WRAM_END = WRAM_START + 0x2000;\n\n  const ROOM = { group: 24, number: 7 }; // PLAYERS_HOUSE_2F\n\n  // Tile ids in wTilemap -> characters (see constants/charmap.asm).\n  const CHARS = { 0x7f: \" \", 0x75: \"…\", 0xe0: \"'\", 0xe3: \"-\", 0xe6: \"?\", 0xe7: \"!\", 0xe8: \".\", 0xe9: \"&\",\n    0xea: \"é\", 0xed: \"▶\", 0xee: \"▼\", 0xef: \"♂\", 0xf0: \"¥\", 0xf3: \"/\", 0xf4: \",\", 0xf5: \"♀\", 0x9a: \"(\", 0x9b: \")\",\n    0x9c: \":\", 0x9d: \";\", 0x9e: \"[\", 0x9f: \"]\", 0x72: \"“\", 0x73: \"”\", 0xd4: \"'s\", 0xd5: \"'t\", 0xd0: \"'d\",\n    0xd1: \"'l\", 0xd2: \"'m\", 0xd3: \"'r\", 0xd6: \"'v\" };\n  for (let i = 0; i < 26; i++) {\n    CHARS[0x80 + i] = String.fromCharCode(65 + i);\n    CHARS[0xa0 + i] = String.fromCharCode(97 + i);\n  }\n  for (let i = 0; i < 10; i++) CHARS[0xf6 + i] = String(i);\n\n  const decode = (tiles, from, to) => {\n    let s = \"\";\n    for (let i = from; i < to; i++) s += CHARS[tiles[i]] ?? (tiles[i] === 0x7f ? \" \" : \"\\u0000\");\n    return s.replace(/\\u0000+/g, \"\").replace(/\\s+$/g, \"\");\n  };\n\n  let wb, root, scenes, current = null, currentId = null, busy = false, timer = null;\n  const flags = { seenNaming: false };\n  const listeners = [];\n\n  function readState(mem) {\n    const at = (sym) => mem[HD_SYMS[sym] - 0xc000];\n    const tiles = mem.subarray(HD_SYMS.wTilemap - 0xc000, HD_SYMS.wTilemap - 0xc000 + 360);\n    const rows = [];\n    for (let r = 0; r < 18; r++) rows.push(decode(tiles, r * 20, r * 20 + 20));\n    return {\n      scene: at(\"wHDScene\"),\n      tiles, rows,\n      map: { group: at(\"wMapGroup\"), number: at(\"wMapNumber\") },\n      x: at(\"wXCoord\"), y: at(\"wYCoord\"),\n      dir: (at(\"wPlayerDirection\") >> 2) & 3, // 0 down, 1 up, 2 left, 3 right\n      species: at(\"wCurPartySpecies\"),\n      naming: (() => {\n        const p = mem[HD_SYMS.wNamingScreenCursorObjectPointer - 0xc000] | (mem[HD_SYMS.wNamingScreenCursorObjectPointer + 1 - 0xc000] << 8);\n        if (p < 0xc000 || p > 0xdfff) return null;\n        return { col: mem[p + 12 - 0xc000], row: mem[p + 13 - 0xc000], max: at(\"wNamingScreenMaxNameLength\") };\n      })(),\n      name: (() => {\n        const o = HD_SYMS.wPlayerName - 0xc000;\n        let n = \"\";\n        for (let i = 0; i < 8 && mem[o + i] !== 0x50; i++) n += CHARS[mem[o + i]] ?? \"\";\n        return n;\n      })(),\n      cursorRow: at(\"wMenuCursorY\"),\n      // A dialogue box is the bordered text window on rows 12-17.\n      dialogue: tiles[12 * 20] === 0x79 && tiles[17 * 20] === 0x7d\n        ? { lines: [decode(tiles, 14 * 20 + 1, 14 * 20 + 19), decode(tiles, 16 * 20 + 1, 16 * 20 + 19)],\n            more: tiles[16 * 20 + 18] === 0xee }\n        : null,\n    };\n  }\n\n  const text = (state, row, from, to) => decode(state.tiles, row * 20 + from, row * 20 + to);\n  // Known characters on a row with their exact tile columns.\n  const cells = (state, row) => {\n    const out = [];\n    for (let c = 0; c < 20; c++) {\n      const ch = CHARS[state.tiles[row * 20 + c]];\n      if (ch && ch !== \" \") out.push({ col: c, ch });\n    }\n    return out;\n  };\n\n  function pick(state) {\n    switch (state.scene) {\n      case 1: return \"title\";\n      case 2: return \"menu\";\n      case 3: return \"clock\";\n      case 4: return \"prof\";\n      case 5: return \"names\";\n      case 6: return \"naming\";\n      case 0:\n        return state.map.group === ROOM.group && state.map.number === ROOM.number ? \"room\" : null;\n      default: return null;\n    }\n  }\n\n  function show(id) {\n    if (id === currentId) return;\n    if (current && current.destroy) current.destroy();\n    root.textContent = \"\";\n    current = id ? scenes[id](root, flags) : null;\n    currentId = id;\n    root.parentElement.classList.toggle(\"hd-on\", !!id);\n    root.dataset.scene = id || \"\";\n  }\n\n  async function tick() {\n    if (busy) return;\n    busy = true;\n    try {\n      const mem = await wb._getWasmMemorySection(WRAM_START, WRAM_END);\n      const state = readState(mem);\n      if (state.scene === 5 || state.scene === 6) flags.seenNaming = true;\n      if (state.scene === 1 || state.scene === 2) flags.seenNaming = false;\n      show(pick(state));\n      if (current) current.update(state);\n      HD.last = state;\n    } catch (err) {\n      console.warn(\"HD tick failed\", err);\n    } finally {\n      busy = false;\n    }\n  }\n\n  return {\n    last: null, text, cells, decode,\n    start(emulator, rootEl, sceneTable) {\n      wb = emulator; root = rootEl; scenes = sceneTable;\n      timer = setInterval(tick, 1000 / 30);\n    },\n    stop() { clearInterval(timer); show(null); },\n  };\n})();\n\n/* syms.js */\nconst HD_SYMS = {\"wHDScene\": 49615, \"wTilemap\": 50080, \"wNamingScreenCurNameLength\": 50642, \"wNamingScreenMaxNameLength\": 50643, \"wNamingScreenCursorObjectPointer\": 50645, \"wMenuCursorY\": 52960, \"wCurPartySpecies\": 53252, \"wPlayerName\": 53667, \"wPlayerDirection\": 53765, \"wMapGroup\": 55808, \"wMapNumber\": 55809, \"wYCoord\": 55810, \"wXCoord\": 55811};\n","/style.css":"/* App shell, tuned for a phone (target: Pixel 9, 412x924). Rules: web/docs/UI.md */\n:root { color-scheme: dark; --bg:#0b1022; --panel:#151c3a; --btn:#222b52; --fg:#eef1ff; --accent:#ffc93c; --ink:#0b1730; }\n* { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }\nhtml, body { height:100%; margin:0; }\nbody { background:var(--bg); color:var(--fg); font:16px 'Fredoka',system-ui,sans-serif; display:flex; justify-content:center; overscroll-behavior:none; }\nmain { width:100%; max-width:480px; height:100dvh; display:flex; flex-direction:column; gap:8px;\n  padding:max(8px, env(safe-area-inset-top)) 8px max(8px, env(safe-area-inset-bottom)); }\n\n#screen-wrap { position:relative; flex:1 1 0; min-height:0; display:grid; place-items:center; overflow:hidden; border-radius:16px;\n  background:radial-gradient(90% 70% at 50% 40%, #243a78, #0b1022); }\n#screen { width:100%; aspect-ratio:160/144; image-rendering:pixelated; display:block; background:#000; }\n#start { position:absolute; inset:0; z-index:2; display:flex; gap:8px; align-items:center; justify-content:center; background:#000a; }\n#start[hidden] { display:none; }\n#screen-wrap.hd-on #start { background:transparent; }\n\nbutton, select { min-height:48px; padding:0 18px; font:inherit; font-weight:600; color:var(--fg); background:var(--btn); border:1px solid #3a4680; border-radius:14px; }\nbutton:active { background:var(--accent); color:var(--ink); }\nbutton:disabled { opacity:.4; }\n\n/* touch pad: ~244px tall, every target >= 48px */\n#pad { flex:none; height:244px; position:relative; touch-action:none; user-select:none; -webkit-user-select:none; -webkit-touch-callout:none; }\n#pad[hidden] { display:none; }\n#dpad { position:absolute; left:6px; top:36px; width:172px; height:172px; border-radius:50%; background:var(--panel); border:2px solid #3a4680; }\n#dpad i { position:absolute; width:0; height:0; border:14px solid transparent; opacity:.55; }\n#dpad .u { left:58px; top:8px; border-bottom:20px solid var(--fg); border-top:0; }\n#dpad .d { left:58px; bottom:8px; border-top:20px solid var(--fg); border-bottom:0; }\n#dpad .l { top:58px; left:8px; border-right:20px solid var(--fg); border-left:0; }\n#dpad .r { top:58px; right:8px; border-left:20px solid var(--fg); border-right:0; }\n#dpad.UP .u, #dpad.DOWN .d, #dpad.LEFT .l, #dpad.RIGHT .r { opacity:1; filter:drop-shadow(0 0 6px var(--accent)); }\n#pad .ab button { position:absolute; width:84px; height:84px; border-radius:50%; font-size:26px; font-weight:700; }\n#pad .ab [data-key=A] { right:8px; top:48px; } #pad .ab [data-key=B] { right:104px; top:98px; }\n#pad .center { position:absolute; left:50%; bottom:2px; transform:translateX(-50%); display:flex; gap:10px; }\n#pad .center button { min-width:92px; height:48px; border-radius:24px; font-size:15px; }\n#pad button.down { background:var(--accent); color:var(--ink); }\n\n#cloud { flex:none; display:flex; gap:8px; align-items:center; }\n#status { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; opacity:.75; font-size:14px; }\n#cloud button { min-height:44px; padding:0 12px; font-size:14px; }\n.hint { display:none; margin:0; opacity:.6; font-size:13px; text-align:center; }\n@media (hover:hover) and (pointer:fine) { #pad { display:none !important; } .hint { display:block; } main { height:min(100dvh, 900px); } }\n"},"roms":{"gold":""}};

// Cloudflare Worker: serves the browser build of the game and stores each
// player's battery save (cartridge RAM) in KV.
//
//   GET    /api/save/:game   -> raw save bytes, 404 if none
//   PUT    /api/save/:game   -> store raw save bytes
//   DELETE /api/save/:game
//   GET    /api/me           -> { code }   the player's recovery code
//   POST   /api/me           -> { code }   adopt a recovery code (new device)
//
// A player is identified by a random 128-bit code kept in an HttpOnly cookie.
// Anyone holding the code can read and write that player's saves.

const GAMES = new Set(["gold", "silver"]);
const SAVE_SIZE = 0x8000; // MBC3 + 32 KB SRAM, see rgbfix -r 3
const COOKIE = "player";
const CODE_RE = /^[0-9a-f]{32}$/;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) return handleApi(request, env, url);
    // Single-file build (make-worker.js) prepends an EMBEDDED constant; the
    // wrangler build serves public/ through the ASSETS binding instead.
    if (typeof EMBEDDED !== "undefined") return serveEmbedded(url);
    return env.ASSETS.fetch(request);
  },
};

async function handleApi(request, env, url) {
  const cookies = parseCookies(request.headers.get("Cookie"));
  let code = CODE_RE.test(cookies[COOKIE] || "") ? cookies[COOKIE] : null;
  const headers = new Headers();

  if (url.pathname === "/api/me") {
    if (request.method === "POST") {
      const body = await request.json().catch(() => ({}));
      const wanted = String(body.code || "").trim().toLowerCase();
      if (!CODE_RE.test(wanted)) return json({ error: "Invalid code" }, 400);
      code = wanted;
    }
    if (!code) code = newCode();
    setCookie(headers, code);
    return json({ code }, 200, headers);
  }

  const match = url.pathname.match(/^\/api\/save\/([a-z]+)$/);
  if (!match || !GAMES.has(match[1])) return json({ error: "Not found" }, 404);
  if (!code) return json({ error: "No player; call /api/me first" }, 401);
  const key = `save:${code}:${match[1]}`;

  switch (request.method) {
    case "GET": {
      const data = await env.SAVES.get(key, "arrayBuffer");
      if (!data) return json({ error: "No save" }, 404);
      return new Response(data, {
        headers: { "Content-Type": "application/octet-stream", "Cache-Control": "no-store" },
      });
    }
    case "PUT": {
      const data = await request.arrayBuffer();
      if (data.byteLength !== SAVE_SIZE) return json({ error: "Bad save size" }, 400);
      await env.SAVES.put(key, data);
      return json({ ok: true });
    }
    case "DELETE":
      await env.SAVES.delete(key);
      return json({ ok: true });
    default:
      return json({ error: "Method not allowed" }, 405);
  }
}

function newCode() {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}

function setCookie(headers, code) {
  headers.append(
    "Set-Cookie",
    `${COOKIE}=${code}; Path=/; Max-Age=31536000; HttpOnly; Secure; SameSite=Strict`
  );
}

function parseCookies(header) {
  const out = {};
  for (const part of (header || "").split(";")) {
    const i = part.indexOf("=");
    if (i > 0) out[part.slice(0, i).trim()] = part.slice(i + 1).trim();
  }
  return out;
}

function json(body, status = 200, headers = new Headers()) {
  headers.set("Content-Type", "application/json");
  headers.set("Cache-Control", "no-store");
  return new Response(JSON.stringify(body), { status, headers });
}

// --- single-file mode -------------------------------------------------------

const TYPES = {
  html: "text/html; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  css: "text/css; charset=utf-8",
};
const romCache = {};

async function serveEmbedded(url) {
  let path = url.pathname;
  const rom = path.match(/^\/roms\/poke([a-z]+)\.gbc$/);
  if (rom) {
    const gz = EMBEDDED.roms[rom[1]];
    if (!gz) return new Response("Not found", { status: 404 });
    romCache[rom[1]] ||= gunzip(gz);
    return new Response(await romCache[rom[1]], {
      headers: { "Content-Type": "application/octet-stream", "Cache-Control": "private, max-age=3600" },
    });
  }
  if (path === "/") path = "/index.html";
  const body = EMBEDDED.files[path];
  if (body === undefined) return new Response("Not found", { status: 404 });
  return new Response(body, { headers: { "Content-Type": TYPES[path.split(".").pop()] } });
}

async function gunzip(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Response(stream).arrayBuffer();
}
